// Feature G：调用、用量、渠道统计与积分观测的只读查询。
// 所有“成功”都指 outcome IN ('succeeded', 'succeeded_unbilled')；“实际扣除”只计已有账本交易的调用
// （自己的渠道调用不产生账本交易，见 ADR-0027）。
func (q *Queries) ListCalls(ctx context.Context, arg ListCallsParams) ([]ListCallsRow, error) {
	rows, err := q.db.Query(ctx, listCalls,
		arg.ScopeChannelText,
		arg.AccountID,
		arg.ScopeChannelID,
		arg.FinalChannelID,
		arg.ApiKeyID,
		arg.Model,
		arg.Format,
		arg.Outcome,
		arg.Tag,
		arg.RequestID,
		arg.FromTime,
		arg.ToTime,
		arg.MinDuration,
		arg.MaxDuration,
		arg.MinTokens,
		arg.MaxTokens,
		arg.MinCharged,
		arg.MaxCharged,
		arg.BeforeAt,
		arg.BeforeID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListCallsRow
	for rows.Next() {
		var i ListCallsRow
		if err := rows.Scan(
			&i.ID,
			&i.CreatedAt,
			&i.CompletedAt,
			&i.AccountID,
			&i.AccountUsername,
			&i.AccountDisplayName,
			&i.ApiKeyID,
			&i.ApiKeyName,
			&i.ModelID,
			&i.RequestedModel,
			&i.Format,
			&i.Stream,
			&i.Tag,
			&i.Outcome,
			&i.FinalChannelID,
			&i.ChannelName,
			&i.InputTokens,
			&i.OutputTokens,
			&i.CacheWriteTokens,
			&i.CacheReadTokens,
			&i.CostNano,
			&i.FeeNano,
			&i.LedgerTxID,
			&i.TtftMs,
			&i.DurationMs,
			&i.AttemptCount,
			&i.ScopeAttempts,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

