const scrubAttemptErrors = `-- name: ScrubAttemptErrors :execrows
WITH due AS (
    SELECT id FROM calls
    WHERE created_at < $1::timestamptz
      AND EXISTS (SELECT 1 FROM jsonb_array_elements(attempts) a WHERE jsonb_typeof(a->'error_message') = 'string')
    ORDER BY created_at
    LIMIT $2
)
UPDATE calls c
SET attempts = (
    SELECT coalesce(jsonb_agg(CASE WHEN jsonb_typeof(t.a->'error_message') = 'string' THEN jsonb_set(t.a, '{error_message}', 'null'::jsonb) ELSE t.a END ORDER BY t.ord), '[]'::jsonb)
    FROM jsonb_array_elements(c.attempts) WITH ORDINALITY AS t(a, ord)
)
FROM due
WHERE c.id = due.id
`

type ScrubAttemptErrorsParams struct {
	Before   time.Time
	RowLimit int32
}

// 原始错误只保留 30 天：清空 attempts 中的 error_message，保留状态码与错误码。
func (q *Queries) ScrubAttemptErrors(ctx context.Context, arg ScrubAttemptErrorsParams) (int64, error) {
	result, err := q.db.Exec(ctx, scrubAttemptErrors, arg.Before, arg.RowLimit)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const usageRevenue = `-- name: UsageRevenue :many
SELECT CASE $1::text
         WHEN 'day' THEN to_char(c.created_at AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD')
         WHEN 'model' THEN coalesce(c.model_id, c.requested_model)
         ELSE c.final_channel_id::text
       END::text AS group_key,
       coalesce(max(ch.name), '')::text AS label,
       count(*)::bigint AS calls,
       count(*) FILTER (WHERE c.outcome IN ('succeeded', 'succeeded_unbilled'))::bigint AS succeeded,
       coalesce(sum(c.input_tokens), 0)::bigint AS input_tokens,
       coalesce(sum(c.output_tokens), 0)::bigint AS output_tokens,
       coalesce(sum(c.cache_write_tokens), 0)::bigint AS cache_write_tokens,
       coalesce(sum(c.cache_read_tokens), 0)::bigint AS cache_read_tokens,
       coalesce(sum(CASE WHEN c.ledger_tx_id IS NULL THEN 0 ELSE c.cost_nano END), 0)::bigint AS amount_nano
FROM calls c
JOIN channels ch ON ch.id = c.final_channel_id
WHERE ch.owner_id = $2::uuid
  AND c.outcome IN ('succeeded', 'succeeded_unbilled', 'interrupted', 'client_disconnected')
  AND c.created_at >= $3::timestamptz AND c.created_at < $4::timestamptz
  AND ($5::uuid IS NULL OR c.final_channel_id = $5::uuid)
  AND ($6::text IS NULL OR c.model_id = $6::text)
GROUP BY 1
ORDER BY 1
`

type UsageRevenueParams struct {
	GroupBy   string
	OwnerID   string
	FromTime  time.Time
	ToTime    time.Time
	ChannelID *string
	Model     *string
}

type UsageRevenueRow struct {
	GroupKey         string
	Label            string
	Calls            int64
	Succeeded        int64
	InputTokens      int64
	OutputTokens     int64
	CacheWriteTokens int64
	CacheReadTokens  int64
	AmountNano       int64
}

func (q *Queries) UsageRevenue(ctx context.Context, arg UsageRevenueParams) ([]UsageRevenueRow, error) {
	rows, err := q.db.Query(ctx, usageRevenue,
		arg.GroupBy,
		arg.OwnerID,
		arg.FromTime,
		arg.ToTime,
		arg.ChannelID,
		arg.Model,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UsageRevenueRow
	for rows.Next() {
		var i UsageRevenueRow
		if err := rows.Scan(
			&i.GroupKey,
			&i.Label,
			&i.Calls,
			&i.Succeeded,
			&i.InputTokens,
			&i.OutputTokens,
			&i.CacheWriteTokens,
			&i.CacheReadTokens,
			&i.AmountNano,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const usageSpend = `-- name: UsageSpend :many
SELECT CASE $1::text
         WHEN 'day' THEN to_char(c.created_at AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD')
         WHEN 'model' THEN coalesce(c.model_id, c.requested_model)
         WHEN 'key' THEN coalesce(c.api_key_id::text, '')
         ELSE coalesce(c.tag, '')
       END::text AS group_key,
       coalesce(max(k.name), '')::text AS label,
       count(*)::bigint AS calls,
       count(*) FILTER (WHERE c.outcome IN ('succeeded', 'succeeded_unbilled'))::bigint AS succeeded,
       coalesce(sum(c.input_tokens), 0)::bigint AS input_tokens,
       coalesce(sum(c.output_tokens), 0)::bigint AS output_tokens,
       coalesce(sum(c.cache_write_tokens), 0)::bigint AS cache_write_tokens,
       coalesce(sum(c.cache_read_tokens), 0)::bigint AS cache_read_tokens,
       coalesce(sum(CASE WHEN c.ledger_tx_id IS NULL THEN 0 ELSE c.cost_nano + c.fee_nano END), 0)::bigint AS amount_nano
FROM calls c
LEFT JOIN api_keys k ON k.id = c.api_key_id
WHERE c.account_id = $2::uuid
  AND c.outcome <> 'in_progress'
  AND c.created_at >= $3::timestamptz AND c.created_at < $4::timestamptz
  AND ($5::uuid IS NULL OR c.api_key_id = $5::uuid)
  AND ($6::text IS NULL OR c.model_id = $6::text OR c.requested_model = $6::text)
  AND ($7::text IS NULL OR c.tag = $7::text)
GROUP BY 1
ORDER BY 1
`

